import type { BankItem, Difficulty } from '../types';

// [KD, subtopik, kesulitan, Bloom, stimulus, opsi (kunci selalu pertama), pembahasan, alasan kunci?, tip?, alasan kesulitan?]. Tiga elemen terakhir hanya
// ada pada butir hasil revisi akademik: tanpa alasan kunci, alasan opsi kunci memakai pembahasan; tanpa tip, butir tidak punya tip; tanpa alasan
// kesulitan, dipakai kalimat baku menurut tingkatnya. Alasan pengecoh ada di `misconceptions` (indeks butir sama, urutan sama dengan opsi 2–5).
type Item = [string, string, Difficulty, string, string, string[], string, string?, string?, string?];
const constitution = 'UUD NRI 1945 — https://www.dpr.go.id/dokumen/jdih/undang-undang-dasar';
const eyd = 'EYD V — https://ejaan.kemendikdasmen.go.id/eyd/';
const items: Item[] = [
  ['Nasionalisme', 'Persatuan dan identitas', 'mudah', 'C2', 'Panitia festival mengizinkan setiap daerah menampilkan budayanya sambil menggunakan bahasa Indonesia dalam koordinasi bersama. Prinsip nasionalisme yang paling langsung tercermin adalah ...', ['Kesatuan politik yang mengakomodasi keragaman budaya.', 'Penyatuan seluruh kebiasaan menjadi satu budaya daerah.', 'Pengutamaan daerah dengan peserta paling banyak.', 'Pemisahan kerja sama berdasarkan asal peserta.', 'Penggantian identitas daerah dengan identitas panitia.'], 'Persatuan mengikat tujuan bersama tanpa menghapus identitas budaya; bahasa Indonesia menjadi penghubung.'],
  ['Nasionalisme', 'Kepentingan bersama', 'sedang', 'C3', 'Dua desa menggunakan satu sumber air. Desa hulu ingin menutup akses desa hilir demi mengamankan seluruh cadangannya, padahal kebutuhan dasar keduanya masih dapat dipenuhi. Usulan yang paling sesuai kepentingan bersama adalah ...', ['Pembagian air berdasarkan kebutuhan dasar dan kesepakatan kedua desa.', 'Pembagian air berdasarkan letak desa terhadap sumbernya.', 'Pembagian air berdasarkan jumlah dana yang disumbangkan.', 'Pembagian air berdasarkan siapa yang lebih dahulu mengajukan.', 'Pembagian air berdasarkan hasil pemungutan suara desa hulu.'], 'Tujuan bersama perlu mempertimbangkan kebutuhan kedua pihak; kedekatan, dana, dan urutan pengajuan belum menjamin pemenuhan kebutuhan dasar.'],
  ['Nasionalisme', 'Kritik dan tanggung jawab', 'sedang', 'C3', 'Warga menyampaikan kritik berbasis data terhadap layanan pemerintah dan mengusulkan perbaikan melalui forum resmi. Sikap tersebut menunjukkan ...', ['Partisipasi warga untuk memperbaiki penyelenggaraan negara.', 'Penolakan terhadap seluruh kewenangan pemerintahan.', 'Pengalihan tanggung jawab pelayanan kepada warga.', 'Pengutamaan kebebasan tanpa mempertimbangkan bukti.', 'Penggantian keputusan pemerintah dengan pendapat pribadi.'], 'Kritik yang dapat dipertanggungjawabkan merupakan partisipasi; ketidaksetujuan terhadap layanan tidak dengan sendirinya menolak negara.'],
  ['Nasionalisme', 'Persatuan dan hak warga', 'sulit', 'C4', 'Program persatuan mensyaratkan peserta menanggalkan bahasa daerah bahkan di luar forum bersama. Bahasa Indonesia sudah digunakan untuk komunikasi kegiatan. Bagian kebijakan yang perlu diperbaiki adalah ...', ['Pembatasan identitas di luar kebutuhan komunikasi kegiatan.', 'Pemakaian bahasa Indonesia dalam koordinasi kegiatan.', 'Pelibatan peserta yang berasal dari berbagai daerah.', 'Penyediaan forum untuk membahas tujuan bersama.', 'Penggunaan satu jadwal untuk kegiatan bersama.'], 'Keperluan komunikasi bersama tidak membenarkan pembatasan identitas di semua ruang; bedakan kesatuan dengan penyeragaman.'],
  ['Nasionalisme', 'Cinta tanah air', 'sedang', 'C3', 'Sebuah jembatan penyeberangan kecil dipakai warga tiga RT untuk menuju pasar dan sekolah. Papan dan pegangan jembatan sering longgar, sedangkan konstruksi utama, seperti tiang penyangga, hanya boleh ditangani petugas dinas pekerjaan umum. Warga dari ketiga RT ingin ikut menjaga jembatan itu. Tindakan yang paling mencerminkan cinta tanah air melalui kepedulian pada fasilitas umum adalah ...', ['Menyusun jadwal kerja bakti bergilir warga tiga RT untuk mengencangkan papan dan pegangan jembatan.', 'Melaporkan papan dan pegangan yang longgar kepada dinas pekerjaan umum untuk diperbaiki petugas.', 'Mengumpulkan iuran warga tiga RT untuk mengganti papan jembatan dalam satu kali kerja bakti.', 'Memperkuat tiang penyangga jembatan dengan cor semen secara swadaya bersama warga dari tiga RT.', 'Mengencangkan papan dan pegangan secara rutin di bagian jembatan yang paling dekat dengan RT sendiri.'], 'Konsep dalam soal ini menekankan cinta tanah air yang diwujudkan sebagai tanggung jawab menjaga fasilitas umum secara adil, berkelanjutan, dan sesuai batas wewenang. Jembatan dalam kasus dipakai warga tiga RT, papan dan pegangannya sering longgar, dan konstruksi utama seperti tiang penyangga hanya boleh ditangani petugas dinas pekerjaan umum. Jadwal kerja bakti bergilir warga tiga RT untuk mengencangkan papan dan pegangan menjangkau semua pengguna, berlangsung terus, dan tidak melampaui wewenang warga sehingga tindakan itu paling tepat. Melaporkan kerusakan ringan kepada dinas benar tetapi belum memadai karena tidak memakai kesediaan warga yang ingin ikut menjaga. Mengganti papan sekali saja atau merawat hanya bagian dekat RT sendiri sama-sama peduli, tetapi keberlanjutan atau jangkauannya kurang, dan memperkuat tiang penyangga melampaui wewenang warga.', 'Perawatan bergilir menjangkau seluruh pengguna, menjawab kerusakan ringan yang berulang, dan berada dalam batas wewenang warga.', 'Bandingkan setiap tindakan dari tiga sisi: siapa pengguna yang terjangkau, apakah manfaatnya berlanjut, dan apakah tindakan masih dalam batas wewenang warga.', 'Menerapkan konsep pada kasus konkret dan membandingkan tindakan peduli yang berbeda jangkauan, keberlanjutan, dan batas wewenang; belum dikalibrasi dari peserta.'],
  ['Nasionalisme', 'Patriotisme dan chauvinisme', 'sedang', 'C2', 'Seorang atlet bulu tangkis muda menolak tawaran klub luar negeri yang menjanjikan penghasilan lebih besar karena jadwal klub itu bentrok dengan seleksi tim nasional. Dalam wawancara, ia menyatakan bangga dapat membela Merah Putih. Ketika tim nasional kalah di final, ia menyalami para pemain lawan dan mengakui bahwa mereka bermain lebih baik hari itu. Ditinjau dari pembedaan paham kebangsaan, sikap atlet tersebut paling tepat digolongkan sebagai ...', ['Patriotisme', 'Chauvinisme', 'Internasionalisme', 'Kosmopolitanisme', 'Primordialisme'], 'Konsep dalam soal ini menekankan pembedaan patriotisme dari chauvinisme, dua sikap terhadap bangsa sendiri yang sering tertukar. Patriotisme adalah semangat mencintai tanah air yang disertai kerelaan berkorban, sedangkan chauvinisme membanggakan bangsa sendiri sambil merendahkan bangsa lain. Dalam kasus ini, atlet melepaskan tawaran penghasilan yang lebih besar demi seleksi tim nasional dan menyatakan bangga membela Merah Putih, yang menjadi bukti pengorbanan dan kecintaan pada tanah air. Ia juga menyalami lawan dan mengakui keunggulan mereka, yang menjadi bukti bahwa ia tidak merendahkan bangsa lain. Karena itu, sikapnya paling tepat digolongkan sebagai patriotisme. Chauvinisme menjadi pengecoh terdekat karena sama-sama berangkat dari kebanggaan pada bangsa, tetapi tidak sesuai karena atlet menghormati lawan. Internasionalisme juga dekat karena sikap sportif atlet, tetapi sportivitas belum menunjukkan kerja sama antarbangsa dan bukan inti tindakannya.', 'Atlet melepaskan penghasilan yang lebih besar, menyatakan bangga membela Merah Putih, dan tetap menghormati lawan; itulah cinta tanah air yang disertai kerelaan berkorban tanpa merendahkan bangsa lain.', 'Pisahkan bukti sikap tokoh terhadap bangsanya sendiri dari bukti sikapnya terhadap bangsa lain, lalu cocokkan keduanya dengan batas pengertian tiap paham.', 'Membedakan dua paham yang berdekatan, patriotisme dan chauvinisme, dari bukti perilaku dalam kasus; belum dikalibrasi dari peserta.'],
  ['Nasionalisme', 'Partisipasi pembangunan', 'sulit', 'C4', 'Proyek fasilitas bersama diusulkan mayoritas warga, tetapi rancangan akses membuat warga penyandang disabilitas tidak dapat menggunakannya. Dana untuk penyesuaian masih tersedia. Evaluasi yang tepat adalah ...', ['Dukungan mayoritas perlu disertai akses yang dapat digunakan warga terdampak.', 'Dukungan mayoritas sudah cukup menggantikan penilaian akses fasilitas.', 'Perbedaan kebutuhan akses sebaiknya ditangani sesudah proyek selesai.', 'Manfaat proyek hanya perlu dihitung dari jumlah pendukung rancangan.', 'Biaya akses tambahan harus dibebankan seluruhnya kepada pengguna disabilitas.'], 'Kepentingan bersama meliputi akses bagi kelompok yang berbeda kebutuhan; persetujuan mayoritas tidak menyelesaikan hambatan akses.'],
  ['Nasionalisme', 'Identitas nasional', 'mudah', 'C1', 'Dalam koordinasi kegiatan nasional, bahasa yang berfungsi sebagai bahasa negara menurut UUD NRI 1945 adalah ...', ['Bahasa Indonesia.', 'Bahasa daerah penyelenggara.', 'Bahasa daerah peserta terbanyak.', 'Bahasa asing mitra kegiatan.', 'Bahasa yang dipilih setiap panitia.'], 'Pasal 36 menetapkan bahasa Indonesia sebagai bahasa negara.'],
  ['Integritas', 'Konflik kepentingan', 'sedang', 'C3', 'Penilai pengadaan mengetahui bahwa salah satu peserta adalah perusahaan keluarganya. Ia belum melakukan penilaian. Tindakan yang paling menjaga independensi adalah ...', ['Mengungkap hubungan dan meminta penanganan konflik kepentingan.', 'Memakai bobot penilaian yang lebih berat untuk perusahaan keluarganya.', 'Menilai sendiri dengan janji tidak membahas hubungan keluarga.', 'Meminta perusahaan keluarganya mengubah nama kontak penawaran.', 'Menunggu hasil penilaian sebelum mengungkap hubungan keluarga.'], 'Pengungkapan memungkinkan konflik ditangani sebelum memengaruhi keputusan; memberi bobot khusus tetap tidak independen.'],
  ['Integritas', 'Kejujuran data', 'mudah', 'C2', 'Laporan kegiatan memuat jumlah peserta yang lebih besar daripada daftar hadir. Pilihan yang mencerminkan kejujuran adalah ...', ['Menggunakan jumlah yang dapat didukung daftar hadir.', 'Menggunakan jumlah pada rencana kegiatan semula.', 'Menggunakan jumlah terbesar dari perkiraan panitia.', 'Menggunakan rata-rata perkiraan beberapa anggota.', 'Menggunakan jumlah yang memudahkan pencapaian target.'], 'Pelaporan harus sesuai bukti; target dan perkiraan tidak menggantikan kehadiran aktual.'],
  ['Integritas', 'Akuntabilitas koreksi', 'sedang', 'C3', 'Anda menemukan kesalahan dalam laporan yang sudah dipakai unit lain. Koreksi yang paling dapat dipertanggungjawabkan adalah ...', ['Mengirim versi koreksi dengan penjelasan perubahan kepada penerima.', 'Mengganti berkas lama tanpa memberi tahu unit penerima.', 'Mengoreksi catatan pribadi untuk laporan periode berikutnya.', 'Meminta penerima menyesuaikan sendiri angka yang keliru.', 'Mengubah angka agregat agar hasil akhir tampak konsisten.'], 'Akuntabilitas memerlukan jejak koreksi dan pemberitahuan agar penerima tidak terus menggunakan versi salah.'],
  ['Integritas', 'Tekanan target', 'sulit', 'C4', 'Atasan meminta data sementara ditulis sebagai realisasi final agar target terlihat tercapai. Sebagian data memang telah diverifikasi. Respons yang paling menjaga integritas sekaligus kegunaan laporan adalah ...', ['Memisahkan realisasi terverifikasi dari data sementara beserta statusnya.', 'Menggabungkan semua data dengan catatan verifikasi masih berjalan.', 'Menghapus seluruh data sampai verifikasi selesai tanpa memberi status.', 'Memakai angka target sebagai pendekatan realisasi untuk laporan ini.', 'Meminta rekan menandatangani data sementara sebagai realisasi final.'], 'Pemisahan status menjaga akurasi dan tetap menyediakan informasi yang telah valid; satu catatan umum tidak mengubah data sementara menjadi realisasi.'],
  ['Integritas', 'Konsistensi tindakan', 'mudah', 'C2', 'Petugas menerapkan persyaratan yang sama kepada temannya dan pemohon lain dengan keadaan yang sama. Nilai integritas yang paling langsung tampak adalah ...', ['Konsistensi antara aturan dan tindakan.', 'Kecepatan menyelesaikan setiap permohonan.', 'Penguasaan teknologi dalam pelayanan.', 'Keberanian membuat pengecualian layanan.', 'Kemampuan membangun relasi personal.'], 'Integritas terlihat dari konsistensi penerapan aturan, termasuk ketika ada hubungan pribadi.'],
  ['Integritas', 'Akses informasi', 'sedang', 'C3', 'Rekan meminta kata sandi akun Anda agar pekerjaan cepat selesai. Akun resmi lain dapat diajukan melalui administrator. Respons yang tepat adalah ...', ['Meminta akses resmi sesuai peran untuk rekan tersebut.', 'Meminjamkan kata sandi lalu menggantinya setelah pekerjaan selesai.', 'Memakai satu akun bersama dengan mencatat nama pengguna di kertas.', 'Mengirim kata sandi melalui pesan yang akan terhapus otomatis.', 'Mengizinkan rekan memakai akun saat Anda berada di ruangan.'], 'Akses sesuai peran menjaga identitas tindakan dan tanggung jawab; kehadiran pemilik akun tidak menggantikan autentikasi pribadi.'],
  ['Integritas', 'Independensi evaluasi', 'sulit', 'C4', 'Tim ingin menghapus temuan kecil dari laporan evaluasi karena perbaikan sudah dijanjikan. Temuan terbukti, tetapi tindak lanjut belum dilaksanakan. Penyajian yang tepat adalah ...', ['Mencatat temuan beserta rencana tindak lanjut dan status pelaksanaannya.', 'Menghapus temuan lalu menambahkannya kembali jika janji tidak dipenuhi.', 'Menulis temuan sebagai selesai karena sudah ada komitmen perbaikan.', 'Menurunkan bobot temuan berdasarkan hubungan baik dengan unit terkait.', 'Mengganti temuan dengan apresiasi atas kesediaan unit memperbaiki.'], 'Temuan dan tindak lanjut mempunyai status berbeda; janji tidak sama dengan bukti pelaksanaan.'],
  ['Integritas', 'Tanggung jawab', 'mudah', 'C2', 'Pegawai merusakkan alat kantor saat bertugas dan segera melaporkan kejadian sesuai prosedur. Sikap tersebut terutama menunjukkan ...', ['Kesediaan mempertanggungjawabkan tindakan.', 'Kemampuan menghindari seluruh risiko kerja.', 'Keberhasilan menjaga citra unit di semua situasi.', 'Kewenangan menentukan ganti rugi sendiri.', 'Keahlian memperbaiki setiap peralatan.'], 'Pelaporan mengakui kejadian dan membuka penanganan yang dapat ditelusuri; tidak membuktikan kewenangan atau keahlian teknis tambahan.'],
  ['Bela Negara', 'Dasar konstitusional', 'mudah', 'C1', 'Hak dan kewajiban warga untuk ikut serta dalam upaya pembelaan negara dinyatakan dalam UUD NRI 1945 pada ...', ['Pasal 27 ayat (3).', 'Pasal 27 ayat (1).', 'Pasal 28D ayat (1).', 'Pasal 31 ayat (1).', 'Pasal 36.'], 'Pasal 27 ayat (3) mengatur partisipasi dalam upaya pembelaan negara; pasal lain pada opsi membahas bidang berbeda.'],
  ['Bela Negara', 'Kontribusi sesuai profesi', 'mudah', 'C2', 'Dalam penanganan wabah penyakit menular di sebuah kabupaten, seorang analis data bekerja sama dengan dinas kesehatan untuk memetakan sebaran kasus dan kebutuhan fasilitas kesehatan memakai data terverifikasi. Ia tidak menentukan tindakan medis bagi pasien. Hubungan antara kontribusi analis tersebut dan bela negara paling tepat dinyatakan sebagai ...', ['Kontribusi sesuai profesi dalam menghadapi wabah merupakan salah satu bentuk bela negara nonmiliter.', 'Kontribusi tergolong bela negara apabila dilakukan dalam tugas pertahanan negara oleh aparat pertahanan.', 'Kontribusi tergolong bela negara yang mengambil alih tugas dinas kesehatan dalam penanganan wabah di kabupaten.', 'Kontribusi tergolong bela negara apabila analis ikut menangani pasien secara langsung di fasilitas kesehatan.', 'Kontribusi merupakan kepedulian sosial warga yang berbeda jenis dari upaya bela negara nonmiliter.'], 'Konsep dalam soal ini menekankan bahwa keikutsertaan warga negara dalam bela negara tidak terbatas pada kegiatan militer, karena Pasal 9 ayat (2) Undang-Undang Nomor 3 Tahun 2002 tentang Pertahanan Negara mengakui pengabdian sesuai dengan profesi sebagai salah satu bentuknya. Wabah termasuk ancaman nonmiliter terhadap keselamatan masyarakat. Analis data dalam kasus ini bekerja sama dengan dinas kesehatan memetakan sebaran kasus dan kebutuhan fasilitas dengan data terverifikasi tanpa menentukan tindakan medis; ia memakai keahliannya dalam batas kompetensi untuk melindungi masyarakat dari ancaman nonmiliter. Karena itu, kontribusinya merupakan salah satu bentuk bela negara nonmiliter. Anggapan bahwa bela negara menuntut tugas pertahanan atau penanganan pasien secara langsung keliru, dan anggapan bahwa analis mengambil alih tugas dinas kesehatan mengabaikan kerja samanya dengan dinas itu. Kepedulian sosial menjadi pengecoh terdekat karena kontribusi itu memang mencerminkan kepedulian, tetapi karena memakai keahlian profesi untuk melindungi masyarakat dari wabah, kontribusi itu juga termasuk bela negara.', 'Memetakan sebaran kasus dan kebutuhan fasilitas dengan data terverifikasi adalah pengabdian sesuai profesi yang melindungi keselamatan masyarakat dari ancaman nonmiliter.', 'Kenali ancaman yang dihadapi dan peran tokoh dalam batas kompetensinya, lalu uji tiap pernyataan terhadap pengertian bela negara menurut peraturan yang berlaku.', 'Memahami hubungan kontribusi profesi dengan bela negara nonmiliter dan menolak empat kesalahan konsep umum; satu langkah penalaran.'],
  ['Bela Negara', 'Ketahanan informasi', 'sedang', 'C3', 'Pesan tentang kerusakan bendungan beredar, tetapi waktu dan lokasi pada foto tidak jelas. Langkah yang mendukung ketahanan informasi adalah ...', ['Memeriksa konteks melalui sumber berwenang sebelum meneruskan pesan.', 'Meneruskan pesan dengan tambahan bahwa kebenarannya belum pasti.', 'Menghitung banyaknya akun yang membagikan pesan sebagai verifikasi.', 'Memakai foto paling baru di grup sebagai bukti lokasi kejadian.', 'Menghapus semua informasi bendungan termasuk pengumuman terverifikasi.'], 'Verifikasi konteks dan sumber mengurangi kepanikan tanpa menutup informasi yang benar.'],
  ['Bela Negara', 'Kesiapsiagaan', 'sedang', 'C4', 'Setelah gempa, seorang warga mendaftar menjadi relawan di posko tanggap darurat kecamatan sebagai wujud bela negara nonmiliter. Ia memegang sertifikat pertolongan pertama dan terbiasa mengemudikan kendaraan bak terbuka, tetapi belum pernah dilatih mengevakuasi korban dari bangunan rusak. Papan informasi posko mencatat bahwa tim evakuasi beranggotakan 12 orang sesuai rencana, tiga perawat di tenda kesehatan melayani sekitar 20 pasien luka ringan per hari tanpa antrean, dan gudang posko menyimpan cukup obat serta air bersih. Namun, dua dusun di perbukitan belum menerima pasokan selama dua hari karena satu-satunya pengemudi posko sakit, padahal kendaraan bak terbuka posko siap dipakai. Kontribusi relawan yang paling tepat adalah ...', ['Mengemudikan kendaraan posko untuk membawa pasokan ke dua dusun atas penugasan koordinator.', 'Membantu tiga perawat di tenda kesehatan dengan bekal sertifikat pertolongan pertama miliknya.', 'Menggalang donasi obat dan air bersih melalui media sosial untuk disalurkan lewat posko kecamatan.', 'Mengikuti pelatihan evakuasi bangunan rusak yang dijadwalkan posko bagi relawan baru kecamatan.', 'Bergabung dengan tim evakuasi setelah menerima arahan singkat dari anggota yang sudah berpengalaman.'], 'Konsep dalam soal ini menekankan bahwa bela negara nonmiliter dalam kesiapsiagaan bencana dilakukan sesuai kompetensi, mengisi kebutuhan yang belum tertangani, dan berada dalam koordinasi posko. Relawan dalam kasus ini memegang sertifikat pertolongan pertama dan terbiasa mengemudikan kendaraan bak terbuka, tetapi belum dilatih memasuki bangunan rusak. Papan informasi posko menunjukkan bahwa tim evakuasi sesuai rencana, tenda kesehatan tanpa antrean, dan gudang cukup obat serta air bersih, sedangkan dua dusun belum menerima pasokan selama dua hari karena satu-satunya pengemudi posko sakit. Karena itu, mengemudikan kendaraan posko untuk membawa pasokan atas penugasan koordinator memadukan kemampuan relawan, kebutuhan yang belum tertangani, dan koordinasi. Membantu perawat paling dekat sebagai pengecoh karena memakai sertifikat relawan, tetapi kebutuhan kesehatan sudah tertangani. Donasi dan pelatihan adalah bentuk kepedulian yang masuk akal, tetapi belum menjawab kebutuhan mendesak saat ini, sedangkan bergabung dengan tim evakuasi menempatkan relawan pada tugas di luar kompetensinya.', 'Keterampilan mengemudi relawan mengisi satu-satunya kebutuhan yang belum tertangani menurut papan informasi posko, dan tindakannya berada dalam penugasan koordinator.', 'Baca data posko untuk menemukan kebutuhan yang belum tertangani, cocokkan dengan kemampuan relawan, lalu pastikan tindakannya berada dalam koordinasi posko.', 'Membaca data posko untuk menemukan kebutuhan yang belum tertangani lalu mencocokkannya dengan kemampuan relawan dan batas kompetensinya; pengecoh berupa bantuan yang masuk akal tetapi kurang tepat. Belum dikalibrasi dari peserta.'],
  ['Bela Negara', 'Kesadaran berbangsa dan bernegara', 'mudah', 'C2', 'Seorang pemilik usaha katering rumahan menghitung dan membayar pajak usahanya tepat waktu setiap tahun. Ia juga hadir dalam musyawarah warga untuk memberi usulan tentang penggunaan dana kelurahan dan menggunakan hak pilihnya pada setiap pemilihan. Dalam kerangka lima nilai dasar bela negara, perilaku tersebut paling menunjukkan nilai ...', ['Sadar berbangsa dan bernegara', 'Cinta tanah air', 'Rela berkorban untuk bangsa dan negara', 'Setia pada Pancasila sebagai ideologi negara', 'Kemampuan awal bela negara'], 'Konsep dalam soal ini menekankan nilai sadar berbangsa dan bernegara, salah satu dari lima nilai dasar bela negara dalam Undang-Undang Nomor 23 Tahun 2019 tentang Pengelolaan Sumber Daya Nasional untuk Pertahanan Negara, yaitu kesadaran menjalankan hak dan kewajiban sebagai warga negara dalam kehidupan berbangsa. Pemilik usaha dalam kasus membayar pajak tepat waktu, menghadiri musyawarah untuk menyampaikan usulan, dan menggunakan hak pilih; ketiganya adalah pelaksanaan kewajiban dan hak warga negara. Karena itu, perilakunya paling menunjukkan sadar berbangsa dan bernegara. Cinta tanah air menjadi pengecoh terdekat karena sama-sama berkaitan dengan hubungan warga dan bangsa, tetapi nilai itu tampak pada rasa bangga dan kepedulian pada tanah air, bukan pada pelaksanaan hak dan kewajiban warga negara.', 'Membayar pajak, menghadiri musyawarah, dan menggunakan hak pilih menunjukkan pemahaman akan hak dan kewajiban sebagai warga negara dalam kehidupan berbangsa.', 'Cocokkan perilaku dalam kasus dengan indikator tiap nilai dasar, dan bedakan nilai yang berdekatan dari apa yang sebenarnya dilakukan tokoh.', 'Mengenali satu nilai dasar bela negara dari perilaku yang menjadi indikatornya; pengecoh berasal dari empat nilai dasar lain.'],
  ['Bela Negara', 'Ketahanan lingkungan', 'sedang', 'C3', 'Kerusakan sumber air mengganggu kesehatan dan mata pencaharian warga. Hubungannya dengan ketahanan masyarakat adalah ...', ['Gangguan lingkungan dapat melemahkan keselamatan dan keberlanjutan hidup.', 'Gangguan lingkungan hanya berpengaruh pada tampilan kawasan.', 'Ketahanan baru terdampak ketika terjadi ancaman bersenjata.', 'Dampak kesehatan dapat dipisahkan dari seluruh kebutuhan air.', 'Mata pencaharian warga tidak berhubungan dengan sumber daya setempat.'], 'Ketahanan meliputi kemampuan masyarakat mempertahankan kebutuhan hidup, termasuk kesehatan dan sumber daya.'],
  ['Bela Negara', 'Koordinasi bantuan', 'sedang', 'C4', 'Pemerintah kabupaten memiliki 900 paket pangan cadangan untuk dua kecamatan yang terdampak kekeringan, dan setiap keluarga terdampak berhak atas satu paket. Kecamatan Lembah memiliki 600 keluarga terdampak dengan persediaan pangan yang masih cukup untuk 7 hari. Kecamatan Pesisir memiliki 300 keluarga terdampak dan persediaan pangannya sudah habis. Kendaraan distribusi hanya dapat melayani satu kecamatan setiap hari, pengiriman dapat dimulai hari ini, dan data kedua kecamatan telah diverifikasi. Skema pengiriman yang paling sesuai dengan upaya menjaga ketahanan pangan warga kedua kecamatan secara adil adalah ...', ['Mengirim 300 paket ke Kecamatan Pesisir hari ini dan 600 paket ke Kecamatan Lembah besok.', 'Mengirim 600 paket ke Kecamatan Lembah hari ini dan 300 paket ke Kecamatan Pesisir besok.', 'Mengirim 300 paket ke Kecamatan Pesisir hari ini, lalu memverifikasi ulang data Kecamatan Lembah sebelum mengirim sisanya.', 'Mengirim 450 paket ke tiap kecamatan, dimulai dari Kecamatan Pesisir hari ini.', 'Mengirim 300 paket ke Kecamatan Pesisir hari ini dan 300 paket ke Kecamatan Lembah besok, lalu menyimpan 300 paket sebagai cadangan kabupaten.'], 'Konsep dalam soal ini menekankan bahwa menjaga ketahanan pangan masyarakat dalam keadaan darurat memerlukan alokasi yang adil menurut kebutuhan dan batas waktu, bukan pembagian sama banyak atau jumlah penduduk semata. Data kasus menunjukkan bahwa 900 paket sama dengan jumlah keluarga yang berhak, persediaan Pesisir sudah habis, persediaan Lembah masih cukup 7 hari, dan kendaraan hanya melayani satu kecamatan per hari. Karena itu, mengirim 300 paket ke Pesisir hari ini dan 600 paket ke Lembah besok memenuhi hak semua keluarga serta tiba sebelum persediaan Lembah habis. Skema yang mendahulukan Lembah membuat Pesisir menunggu sehari tanpa pangan, pembagian sama banyak tidak sesuai jumlah keluarga, dan verifikasi ulang atau cadangan menunda hak keluarga padahal datanya sudah terverifikasi.', 'Pesisir, yang persediaannya sudah habis, dilayani lebih dahulu, dan jumlah paket tiap kecamatan sesuai dengan jumlah keluarga sehingga hak semua keluarga terpenuhi tepat waktu.', 'Catat semua data kasus (jumlah penerima, sisa persediaan, dan kapasitas pengiriman), lalu uji setiap skema terhadap seluruh data itu, bukan terhadap satu angka saja.', 'Membandingkan beberapa skema alokasi terhadap tiga data sekaligus (jumlah keluarga, sisa persediaan, kapasitas pengiriman) dengan hitungan sederhana; belum dikalibrasi dari peserta.'],
  ['Bela Negara', 'Batas kewenangan', 'sedang', 'C3', 'Seorang petugas kecamatan di wilayah perbatasan menerima laporan warga bahwa sebuah patok batas negara di kebun warga tampak bergeser dari posisi semula. Petugas itu belum mengetahui penyebabnya dan tidak bertugas di instansi yang mengelola perbatasan. Tindakan awal yang paling tepat sesuai kewenangan petugas tersebut adalah ...', ['Mendokumentasikan kondisi patok beserta lokasinya, lalu melaporkannya secara berjenjang kepada instansi berwenang.', 'Mengukur ulang posisi patok memakai aplikasi peta di ponsel, lalu mengumumkan hasilnya kepada warga.', 'Mengunggah foto patok ke akun media sosial kecamatan sebagai laporan terbuka kepada instansi terkait.', 'Mengembalikan patok ke posisi yang diingat warga setempat, lalu melaporkannya kepada atasan di kecamatan.', 'Meminta warga pelapor memotret patok setiap hari selama seminggu untuk memastikan pergeserannya, lalu meneruskan laporan kepada atasan.'], 'Konsep dalam soal ini menekankan bahwa bela negara pada urusan wilayah dilakukan sesuai peran dan kewenangan: penetapan serta pengelolaan batas wilayah negara diatur dalam Undang-Undang Nomor 43 Tahun 2008 tentang Wilayah Negara dan ditangani instansi yang berwenang, bukan petugas kecamatan. Petugas dalam kasus ini menerima laporan pergeseran patok, belum mengetahui penyebabnya, dan tidak bertugas di instansi pengelola perbatasan. Karena itu, tindakan awal yang tepat adalah mendokumentasikan kondisi patok beserta lokasinya dan melaporkannya secara berjenjang kepada instansi berwenang. Mengembalikan patok memang bermaksud melindungi wilayah, tetapi mengubah bukti dan bersandar pada ingatan warga. Mengukur ulang dan mengunggah foto melewati jalur resmi, sedangkan memantau dahulu menunda laporan awal yang seharusnya segera disampaikan.', 'Dokumentasi menjaga kondisi patok sebagai bukti, dan laporan berjenjang menyalurkan masalah kepada pihak yang berwenang dalam batas peran petugas.', 'Tentukan siapa yang berwenang atas masalah dalam kasus, lalu pilih tindakan yang menjaga bukti tetap utuh dan menyalurkan masalah kepada pihak tersebut melalui jalur resmi.', 'Menerapkan batas kewenangan pada kasus baru dan membedakan tindakan berniat baik yang melampaui kewenangan dari tindakan yang tepat; belum dikalibrasi dari peserta.'],
  ['Pilar Negara', 'Bentuk negara', 'mudah', 'C1', 'Bentuk negara menurut Pasal 1 ayat (1) UUD NRI 1945 adalah ...', ['Negara kesatuan berbentuk republik.', 'Negara federal berbentuk republik.', 'Negara kesatuan berbentuk monarki.', 'Konfederasi berbentuk republik.', 'Federasi berbentuk monarki.'], 'Pasal 1 ayat (1) menetapkan bentuk kesatuan dan bentuk republik; keduanya perlu dibedakan.'],
  ['Pilar Negara', 'Negara hukum', 'sedang', 'C3', 'Seorang pejabat daerah membuka usaha percetakan, tetapi menolak mengurus izin usaha dengan alasan jabatannya penting. Persyaratan izin itu sudah diumumkan kepada publik dan telah dipenuhi oleh para pemilik percetakan lain. Izin diterbitkan oleh dinas lain yang tidak berada di bawah kewenangan pejabat tersebut. Prinsip negara hukum dalam UUD NRI Tahun 1945 yang paling langsung bertentangan dengan sikap pejabat itu adalah ...', ['Persamaan kedudukan dalam hukum', 'Perlindungan hak milik pribadi', 'Kepastian hukum yang adil', 'Praduga tak bersalah', 'Pembatasan kewenangan pejabat publik'], 'Konsep dalam soal ini menekankan prinsip negara hukum yang menjamin persamaan kedudukan warga di dalam hukum dan pemerintahan (Pasal 27 ayat (1) UUD NRI Tahun 1945). Pasal 28D ayat (1) menjamin pula perlakuan yang sama di hadapan hukum. Pejabat dalam kasus menolak mengurus izin karena jabatannya penting, padahal persyaratan sudah diumumkan, telah dipenuhi pemilik percetakan lain, dan izin diterbitkan dinas lain yang tidak berada di bawah kewenangannya. Penolakan itu berarti meminta perlakuan khusus semata-mata karena jabatan, yang paling langsung bertentangan dengan persamaan kedudukan. Kepastian hukum yang adil menjadi pengecoh terdekat karena Pasal 28D ayat (1) memuat kepastian hukum sekaligus perlakuan yang sama; namun kepastian hukum berkaitan dengan kejelasan aturan, padahal aturan perizinan dalam kasus sudah jelas dan diumumkan, dan yang dipersoalkan adalah pengecualian bagi pejabat. Unsur perlakuan yang sama dalam pasal itu justru mendukung kunci.', 'Pasal 27 ayat (1) menyatakan segala warga negara bersamaan kedudukannya di dalam hukum dan pemerintahan; jabatan tidak membebaskan seseorang dari kewajiban yang telah dipenuhi warga lain dalam keadaan yang sama.', 'Tentukan lebih dahulu apa yang sebenarnya dipersoalkan dalam kasus, yaitu kejelasan aturan, pemakaian wewenang, atau perlakuan khusus yang diminta, lalu pilih prinsip yang menjawab persoalan itu secara langsung, bukan prinsip yang hanya berdekatan.', 'Menerapkan prinsip persamaan di depan hukum pada kasus dan menyingkirkan prinsip tetangga (kepastian hukum, kewenangan, praduga tak bersalah, hak milik); belum dikalibrasi dari peserta.'],
  ['Pilar Negara', 'Musyawarah', 'sedang', 'C3', 'Dua usulan penggunaan dana warga memiliki manfaat berbeda. Sebelum mengambil keputusan, langkah yang sesuai musyawarah adalah ...', ['Membahas alasan dan dampak kedua usulan dengan perwakilan warga.', 'Memilih usulan pertama agar proses keputusan cepat selesai.', 'Memilih usulan kelompok yang paling banyak menyumbang dana.', 'Menyerahkan keputusan kepada penyusun usulan yang paling rinci.', 'Menghitung dukungan tanpa memberi kesempatan menjelaskan kebutuhan.'], 'Musyawarah memberi ruang pertimbangan dan kepentingan bersama; banyak dukungan belum menggantikan pembahasan alasan.'],
  ['Pilar Negara', 'Kesetaraan dan akomodasi', 'sulit', 'C4', 'Kantor menyediakan bantuan membaca formulir bagi pengguna dengan hambatan penglihatan. Antrean dan syarat substantif tetap sama. Penilaian yang paling tepat adalah ...', ['Akomodasi mengurangi hambatan akses tanpa mengubah syarat substantif.', 'Setiap bantuan tambahan merupakan keistimewaan yang menyalahi kesetaraan.', 'Kesetaraan mengharuskan semua pengguna membaca formulir tanpa bantuan.', 'Bantuan akses hanya tepat bila pengguna mengenal petugas layanan.', 'Bantuan formulir otomatis membebaskan pengguna dari syarat layanan.'], 'Kesetaraan akses dapat memerlukan bantuan berbeda; akomodasi tidak sama dengan menghapus persyaratan.'],
  ['Pilar Negara', 'Sila Pancasila', 'mudah', 'C2', 'Sebuah forum memilih keputusan melalui pembahasan perwakilan yang mendengarkan alasan peserta. Sila yang paling langsung tampak dalam cara mengambil keputusan tersebut adalah ...', ['Sila keempat.', 'Sila pertama.', 'Sila kedua.', 'Sila ketiga.', 'Sila kelima.'], 'Cara pengambilan keputusan melalui permusyawaratan dan perwakilan paling langsung berkaitan dengan sila keempat; nilai sila lain dapat mendukung tetapi bukan fokus prosedurnya.'],
  ['Pilar Negara', 'Bhinneka Tunggal Ika', 'sedang', 'C2', 'Semboyan Bhinneka Tunggal Ika dalam kerja sama masyarakat paling tepat dimaknai sebagai ...', ['Perbedaan identitas yang terhubung oleh kesatuan bersama.', 'Kesatuan yang mensyaratkan semua kebiasaan sama.', 'Perbedaan yang meniadakan kewajiban bekerja sama.', 'Kesatuan yang dibentuk oleh dominasi identitas mayoritas.', 'Perbedaan yang hanya diakui dalam kegiatan budaya.'], 'Kesatuan tidak menghapus keragaman atau membatasi pengakuannya hanya pada perayaan budaya.'],
  ['Pilar Negara', 'Hak dan tanggung jawab', 'sulit', 'C4', 'Seorang wali murid menerima kuitansi pungutan di luar ketentuan dari sebuah sekolah negeri. Kuitansi itu memuat nama sekolah dan tanda tangan bendahara, tetapi wali murid belum mengetahui siapa yang memutuskan pungutan tersebut, termasuk apakah kepala sekolah terlibat. Dinas pendidikan menyediakan layanan aduan yang merahasiakan identitas pelapor dan memeriksa setiap aduan yang masuk. Wali murid ingin menggunakan haknya menyampaikan pendapat agar pungutan itu diperiksa, tetapi tidak ingin merugikan kehormatan orang yang belum terbukti bersalah. Berdasarkan ketentuan hak asasi manusia dalam UUD NRI Tahun 1945, tindakan yang paling tepat adalah ...', ['Menyampaikan keberatan disertai kuitansi kepada dinas pendidikan dan meminta pemeriksaan pungutan.', 'Mengunggah foto kuitansi ke grup percakapan wali murid setelah menutup nama dan tanda tangan bendahara.', 'Meminta komite sekolah membahas kuitansi itu dalam rapat terbuka yang dihadiri para wali murid sekolah.', 'Meminta kepala sekolah menghentikan pungutan itu dan melaporkan penyelesaiannya kepada dinas pendidikan.', 'Menulis surat pembaca di media lokal tentang adanya pungutan di sebuah sekolah negeri kabupaten.'], 'Konsep dalam soal ini menekankan bahwa hak asasi manusia dalam UUD NRI Tahun 1945 dijalankan dengan menghormati hak orang lain. Hak mengeluarkan pendapat (Pasal 28E ayat (3)) perlu diseimbangkan dengan hak atas kehormatan dan martabat (Pasal 28G ayat (1)) serta kewajiban menghormati hak asasi orang lain (Pasal 28J ayat (1)). Dalam kasus ini, kuitansi memuat nama sekolah dan tanda tangan bendahara, pihak yang memutuskan pungutan belum diketahui, dan dinas pendidikan memeriksa setiap aduan sambil merahasiakan pelapor. Menyampaikan keberatan disertai kuitansi kepada dinas pendidikan dan meminta pemeriksaan memakai hak berpendapat agar pungutan diperiksa pihak berwenang, sekaligus menjaga kehormatan pihak yang belum terbukti karena tidak menuduh siapa pun. Meminta kepala sekolah menghentikan pungutan secara internal menjadi pengecoh terdekat karena kehormatan terjaga, tetapi kepala sekolah mungkin terlibat dan tidak ada pemeriksaan independen. Mengunggah ke grup percakapan atau membahasnya dalam rapat terbuka menyebarkan dugaan sebelum diperiksa, sedangkan surat pembaca yang tidak menunjuk sekolah tidak dapat ditindaklanjuti.', 'Dinas pendidikan memeriksa setiap aduan dan merahasiakan pelapor, sedangkan meminta pemeriksaan tidak sama dengan menuduh orang tertentu sehingga kehormatan pihak yang belum terbukti tetap terjaga; kedua kepentingan dalam soal terpenuhi.', 'Catat dua syarat yang diminta soal, yaitu pungutan diperiksa pihak yang berwenang dan kehormatan orang yang belum terbukti tetap terjaga, lalu singkirkan tindakan yang hanya memenuhi salah satu syarat.', 'Menimbang dua kepentingan yang sama-sama sah dan menentukan batas tindakan dari fakta kasus; pengecoh berupa tindakan berniat baik tetapi kurang tepat. Belum dikalibrasi dari peserta.'],
  ['Pilar Negara', 'Bahasa dan simbol negara', 'mudah', 'C1', 'Pasangan ketentuan UUD NRI 1945 yang tepat adalah ...', ['Pasal 36: bahasa negara adalah bahasa Indonesia.', 'Pasal 36: bendera negara adalah Merah Putih.', 'Pasal 35: bahasa negara adalah bahasa Indonesia.', 'Pasal 36A: lagu kebangsaan adalah Indonesia Raya.', 'Pasal 36B: lambang negara adalah Garuda Pancasila.'], 'Pasal 35 mengatur bendera, 36 bahasa, 36A lambang, dan 36B lagu kebangsaan.'],
  ['Bahasa Negara', 'Kata depan dan imbuhan', 'mudah', 'C2', 'Kalimat yang penulisan kata depan dan imbuhannya tepat adalah ...', ['Berkas yang diterima di loket diperiksa petugas.', 'Berkas yang di terima di loket diperiksa petugas.', 'Berkas yang diterima diloket diperiksa petugas.', 'Berkas yang diterima di loket di periksa petugas.', 'Berkas yang di terima diloket di periksa petugas.'], 'Konsep dalam soal ini menekankan perbedaan fungsi di sebagai awalan pembentuk kata kerja pasif dan di sebagai kata depan penunjuk tempat (EYD V). Kalimat memuat tiga bentuk, yaitu “diterima”, “di loket”, dan “diperiksa”. Awalan di- pada “diterima” dan “diperiksa” menempel pada kata dasarnya sehingga ditulis serangkai, sedangkan “di loket” menunjukkan tempat sehingga ditulis terpisah. Karena itu, hanya kalimat “Berkas yang diterima di loket diperiksa petugas.” yang ketiga bentuknya tepat. Kalimat dengan “di periksa” dan kalimat dengan “di terima” menjadi pengecoh terdekat karena hanya satu bentuknya yang keliru, yaitu awalan di- yang dipisah dari kata kerjanya.', '“Diterima” dan “diperiksa” adalah kata kerja pasif sehingga awalan di- ditulis serangkai, sedangkan “di loket” menunjukkan tempat sehingga kata depan di ditulis terpisah.', 'Uji setiap di: bila bentuknya kata kerja pasif yang dapat dipadankan dengan bentuk me- (diterima, menerima), tulis serangkai; bila diikuti kata yang menyatakan tempat, tulis terpisah.', 'Mengenali satu kaidah yang dinyatakan: awalan di- serangkai, kata depan di terpisah.'],
  ['Bahasa Negara', 'Penulisan tanda baca', 'sedang', 'C3', '(1) Panitia menyiapkan konsumsi, tenda, dan pengeras suara untuk acara bersih desa. (2) Kepala desa mengatakan, bahwa acara akan dimulai pukul 07.30. (3) Setelah semua peserta hadir, ketua panitia membuka acara. (4) Panitia memindahkan acara ke balai desa, apabila lapangan tergenang. (5) Ketua panitia berkata, “Terima kasih atas kerja sama Bapak dan Ibu.”\nKalimat yang menggunakan tanda baca secara tepat ditunjukkan oleh nomor ...', ['1, 3, dan 5', '1, 2, dan 5', '2, 3, dan 4', '1, 3, dan 4', '3, 4, dan 5'], 'Konsep dalam soal ini menekankan penerapan kaidah tanda koma dan tanda petik dalam EYD V. Kalimat (1) benar karena unsur perincian dipisahkan koma. Kalimat (3) benar karena anak kalimat yang mendahului induk kalimat diikuti koma. Kalimat (5) benar karena petikan langsung didahului koma dan titik berada di dalam tanda petik. Kalimat (2) keliru karena koma tidak dipakai sebelum “bahwa”, dan kalimat (4) keliru karena koma tidak dipakai sebelum anak kalimat yang mengiringi induk kalimat. Dengan demikian, kalimat yang tepat adalah (1), (3), dan (5).', 'Kalimat (1) memakai koma pada perincian, kalimat (3) memakai koma sesudah anak kalimat yang mendahului induk kalimat, dan kalimat (5) memakai koma sebelum petikan langsung serta titik di dalam tanda petik; ketiganya sesuai EYD V.', 'Uji tiap kalimat dengan satu kaidah tanda baca yang relevan, tandai kalimat yang benar, lalu cocokkan hasilnya dengan kombinasi nomor pada pilihan.', 'Menerapkan lima kaidah tanda baca pada lima kalimat lalu menggabungkan hasilnya dalam satu pilihan kombinasi.'],
  ['Bahasa Negara', 'Kalimat efektif', 'mudah', 'C2', 'Panitia menyusun pengumuman pendaftaran ulang bagi peserta pelatihan. Kalimat pengumuman yang efektif adalah ...', ['Peserta wajib membawa kartu identitas asli, mengisi formulir pendaftaran ulang, dan membayar biaya administrasi sebelum memasuki ruang pelatihan hari pertama.', 'Peserta wajib membawa kartu identitas asli, mengisi formulir pendaftaran ulang, serta pembayaran biaya administrasi yang dilakukan di loket sebelum memasuki ruang pelatihan hari pertama.', 'Dalam pendaftaran ulang ini mewajibkan peserta membawa kartu identitas asli, mengisi formulir, dan membayar biaya administrasi sebelum memasuki ruang pelatihan.', 'Peserta wajib membawa kartu identitas asli, mengisi formulir pendaftaran ulang, dan membayar biaya administrasi terlebih dahulu sebelum memasuki ruang pelatihan.', 'Walaupun peserta wajib membawa kartu identitas asli, tetapi peserta juga wajib mengisi formulir pendaftaran ulang dan membayar biaya administrasi.'], 'Konsep dalam soal ini menekankan ciri kalimat efektif, yaitu kesepadanan subjek dan predikat, kepaduan, kesejajaran perincian, dan kehematan kata. Kalimat “Peserta wajib membawa kartu identitas asli, mengisi formulir pendaftaran ulang, dan membayar biaya administrasi sebelum memasuki ruang pelatihan hari pertama.” memiliki subjek “peserta”, predikat “wajib membawa”, dan tiga perincian yang semuanya berupa kata kerja tanpa kata berlebih. Rumusan lain masing-masing memuat satu kekeliruan yang berbeda: perincian tidak sejajar karena “pembayaran biaya administrasi” berupa kata benda, subjek hilang karena “dalam … mewajibkan”, pleonasme “terlebih dahulu … sebelum”, dan konjungsi ganda “walaupun … tetapi”. Rumusan dengan pleonasme menjadi pengecoh terdekat karena susunan intinya sama dengan kalimat yang efektif, tetapi ditambah kata yang mubazir.', 'Subjek (peserta) dan predikat jelas, tiga perincian berupa kata kerja yang sejajar, dan tidak ada kata yang berlebihan.', 'Periksa tiap kalimat dari subjek dan predikatnya, lalu uji kesejajaran perincian, penggunaan konjungsi, dan kata berlebih satu per satu.', 'Mengenali kalimat yang hemat, padu, dan sejajar di antara kalimat dengan empat kekeliruan berbeda.'],
  ['Bahasa Negara', 'Kalimat efektif', 'sedang', 'C3', 'Perbaikan paling tepat untuk kalimat “Bagi peserta yang belum melengkapi berkas harap segera melengkapi” adalah ...', ['Peserta yang belum melengkapi berkas diminta segera melengkapinya.', 'Bagi peserta yang belum melengkapi berkas agar segera melengkapinya.', 'Kepada peserta yang belum melengkapi berkas diminta agar segera.', 'Dari peserta yang belum melengkapi berkas diminta segera melengkapi.', 'Peserta yang belum melengkapi berkas diminta segera dilengkapi.'], 'Konsep dalam soal ini menekankan ciri kalimat efektif: subjek jelas, predikat dan objek lengkap, makna logis, dan tidak ada kata yang berlebihan. Kalimat asal “Bagi peserta yang belum melengkapi berkas harap segera melengkapi” memuat dua galat, yaitu tidak memiliki subjek karena kata depan “bagi” menjadikan kelompok peserta keterangan, dan “melengkapi” tanpa objek. Kalimat “Peserta yang belum melengkapi berkas diminta segera melengkapinya.” memperbaiki keduanya: subjeknya “peserta yang belum melengkapi berkas”, predikatnya “diminta segera melengkapinya”, dan “-nya” merujuk pada berkas sehingga pelaku dan tindakan disebut lengkap. Kalimat berbentuk pasif “dilengkapi” menjadi pengecoh terdekat karena bersubjek, tetapi maknanya tidak logis sebab peserta menjadi pihak yang dilengkapi. Kalimat yang berawal “Kepada peserta” sudah memakai predikat “diminta”, tetapi “agar segera” belum menyebut tindakan yang harus dilakukan. Diawali kata depan tidak otomatis salah; yang menentukan adalah ada atau tidaknya subjek yang jelas, kelengkapan tindakan, dan kelogisan makna.', 'Pelaku (peserta yang belum melengkapi berkas) dan tindakan yang diminta (melengkapinya) disebut lengkap, dengan “-nya” merujuk pada berkas sebagai objek; kalimat bersubjek, berpredikat, dan hemat.', 'Tentukan dahulu siapa yang diminta bertindak dan apa yang harus dilengkapi pada kalimat asal, lalu pilih perbaikan yang menyebut keduanya secara jelas dan logis tanpa menimbulkan kesalahan baru.', 'Menerapkan ciri kalimat efektif (subjek jelas, predikat dan objek lengkap, logis, hemat) dan menolak perbaikan yang masih menyisakan subjek, objek, atau logika yang rusak.'],
  ['Bahasa Negara', 'Ide pokok atau gagasan utama', 'sedang', 'C2', '(1) Sejumlah penggilingan padi kecil di sebuah kabupaten membuang sekam dalam jumlah besar setiap hari. (2) Sebagian penggilingan membakar tumpukan sekam itu di lahan terbuka sehingga warga sekitar mengeluhkan asap. (3) Sebuah koperasi kemudian melatih pengelola penggilingan memadatkan sekam menjadi briket dengan alat sederhana. (4) Briket itu dipakai untuk mengeringkan gabah sehingga biaya bahan bakar penggilingan turun. (5) Sekam padi yang semula menjadi limbah pencemar ternyata dapat menjadi sumber penghematan bagi penggilingan kecil.\nIde pokok paragraf tersebut adalah ...', ['Sekam padi yang tadinya limbah dapat diolah menjadi briket yang menghemat biaya penggilingan kecil.', 'Pembakaran sekam di lahan terbuka oleh penggilingan padi kecil mengganggu warga sekitar dengan asap.', 'Pelatihan dari koperasi menjadi sumber penghematan utama bagi penggilingan padi kecil di kabupaten itu.', 'Briket sekam yang dipakai untuk mengeringkan gabah menurunkan biaya bahan bakar penggilingan.', 'Penggilingan padi kecil sebaiknya berhenti membakar sekam di lahan terbuka dan beralih memakai briket.'], 'Konsep dalam soal ini menekankan ide pokok sebagai gagasan yang melingkupi seluruh kalimat dalam paragraf, berbeda dari rincian. Paragraf ini bersifat induktif: kalimat (1) sampai (4) memaparkan masalah sekam, pembakarannya, pelatihan membuat briket, dan penurunan biaya bahan bakar, lalu kalimat (5) merangkumnya sebagai perubahan sekam dari limbah pencemar menjadi sumber penghematan. Karena itu, gagasan bahwa sekam padi yang tadinya limbah dapat diolah menjadi briket yang menghemat biaya penggilingan kecil paling tepat sebagai ide pokok. Penurunan biaya bahan bakar menjadi pengecoh terdekat karena disebut dalam teks, tetapi pernyataan itu hanya rincian kalimat (4) dan belum mencakup perubahan sekam dari limbah menjadi sumber penghematan. Pernyataan tentang asap dan pelatihan juga rincian, sedangkan saran berhenti membakar sekam melampaui isi teks.', 'Gagasan ini melingkupi seluruh paragraf: sekam yang semula limbah diolah menjadi briket yang menghemat biaya, sebagaimana dirangkum kalimat (5) dan didukung kalimat (1) sampai (4).', 'Tanyakan gagasan mana yang didukung oleh semua kalimat lain, lalu singkirkan pilihan yang hanya merangkum satu rincian atau menambah klaim di luar teks.', 'Menentukan gagasan yang mencakup seluruh paragraf induktif dan membedakannya dari rincian yang benar tetapi sempit atau klaim di luar teks.'],
  ['Bahasa Negara', 'Penalaran isi bacaan', 'sulit', 'C4', 'Tim A mencatat penurunan waktu layanan setelah aplikasi baru dipakai. Pada bulan yang sama, jumlah petugas bertambah. Tim B memakai aplikasi yang sama tanpa tambahan petugas dan waktu layanannya tetap. Kesimpulan paling hati-hati adalah ...', ['Data belum memisahkan pengaruh aplikasi dari tambahan petugas.', 'Aplikasi pasti tidak mempunyai pengaruh pada waktu layanan tim A.', 'Tambahan petugas pasti menjadi satu-satunya penyebab penurunan.', 'Tim B membuktikan aplikasi memperlambat pelayanan di semua unit.', 'Penurunan waktu tim A membuktikan aplikasi efektif di semua unit.'], 'Dua perubahan pada tim A menjadi faktor yang belum dipisahkan; perbandingan tim B tidak membuktikan satu sebab tunggal.'],
  ['Bahasa Negara', 'Rujukan dalam bacaan', 'mudah', 'C2', '(1) Pemerintah desa memasang lampu jalan di dua dusun yang selama ini gelap. (2) Desa juga menambah petugas kebersihan di pasar agar sampah tidak lagi menumpuk. (3) Menurut warga, penerangan itu membuat mereka merasa aman keluar rumah pada malam hari.\nFrasa “penerangan itu” pada kalimat (3) merujuk pada ...', ['Lampu jalan yang dipasang di dua dusun', 'Para petugas kebersihan yang ditambah di pasar', 'Dua dusun yang selama ini masih gelap', 'Sampah pasar yang kini tidak lagi menumpuk', 'Rasa aman warga di dusun pada malam hari'], 'Konsep dalam soal ini menekankan kohesi antarkalimat: frasa penunjuk merujuk pada unsur sebelumnya yang maknanya sepadan dengan kata inti frasa itu. Kata inti “penerangan” sepadan dengan lampu jalan yang dipasang pada kalimat (1), bukan dengan petugas kebersihan pada kalimat (2) yang berkaitan dengan sampah. Kalimat (3) juga menyatakan akibat berupa rasa aman pada malam hari, dan akibat itu selaras dengan adanya lampu jalan. Karena itu, “penerangan itu” merujuk pada lampu jalan yang dipasang di dua dusun. Petugas kebersihan menjadi pengecoh terdekat karena letaknya paling dekat dengan frasa penunjuk, tetapi maknanya tidak sepadan dengan penerangan.', 'Lampu jalan adalah sarana penerangan yang disebut dalam kalimat (1), dan keberadaannya selaras dengan rasa aman pada malam hari.', 'Tentukan kata inti frasa penunjuk, cari unsur pada kalimat sebelumnya yang maknanya sepadan dengan kata inti itu, lalu uji dengan menggantikan frasa tersebut dengan unsur yang ditemukan.', 'Menentukan unsur yang dirujuk frasa penunjuk berdasarkan kesepadanan makna dengan kata inti frasa; satu langkah penalaran.'],
  ['Bahasa Negara', 'Evaluasi pernyataan', 'sulit', 'C4', 'Sebagian peserta memakai materi daring. Semua peserta yang memakai materi daring mendapat akses forum. Tidak semua pemilik akses forum aktif berdiskusi. Pernyataan yang didukung teks adalah ...', ['Peserta yang memakai materi daring memiliki akses, tetapi belum tentu aktif berdiskusi.', 'Semua peserta aktif berdiskusi setelah mendapat materi daring.', 'Peserta tanpa materi daring tidak mungkin mempunyai akses forum.', 'Sebagian pengguna materi daring pasti tidak aktif berdiskusi.', 'Setiap pemilik akses forum pasti memakai materi daring.'], 'Akses tidak sama dengan aktivitas; informasi tidak semua pemilik aktif belum menentukan aktivitas subkelompok pengguna materi daring.'],
];

const misconceptions: string[][] = [
  ['Kesatuan tidak mensyaratkan satu budaya daerah.', 'Jumlah peserta tidak menjadi dasar dominasi.', 'Pemisahan menghilangkan kerja sama yang disebutkan.', 'Identitas panitia tidak menggantikan budaya peserta.'],
  ['Letak geografis tidak menetapkan kebutuhan dasar.', 'Kontribusi dana bukan dasar hak atas kebutuhan dasar.', 'Urutan pengajuan mengabaikan kebutuhan kedua desa.', 'Keputusan satu desa tidak mewakili kepentingan desa lain.'],
  ['Kritik pada layanan berbeda dari penolakan seluruh pemerintahan.', 'Usulan perbaikan tidak memindahkan tugas layanan.', 'Kritik dalam stimulus justru menggunakan bukti.', 'Forum resmi merupakan partisipasi, bukan penggantian kewenangan.'],
  ['Bahasa penghubung sudah diperlukan untuk koordinasi.', 'Peserta berbagai daerah mendukung tujuan persatuan.', 'Pembahasan tujuan bersama sesuai kebutuhan kegiatan.', 'Satu jadwal tidak menghapus identitas di luar kegiatan.'],
  ['Pelaporan itu tepat untuk konstruksi utama, tetapi kerusakan ringan yang berulang dapat ditangani warga sendiri; menyerahkannya kepada petugas tidak memakai kesediaan warga untuk ikut menjaga.', 'Tindakan ini peduli, tetapi hanya satu kali dan tidak menyentuh pegangan yang juga sering longgar sehingga jembatan belum terjaga secara berkelanjutan.', 'Tiang penyangga termasuk konstruksi utama yang hanya boleh ditangani petugas dinas pekerjaan umum; niat baik warga di sini melampaui batas wewenang dan dapat membahayakan pengguna.', 'Perawatan rutin itu baik, tetapi hanya menjangkau sebagian jembatan padahal jembatan dipakai warga tiga RT.'],
  ['Chauvinisme membanggakan bangsa sendiri sambil merendahkan bangsa lain; atlet justru mengakui keunggulan lawan sehingga rasa bangganya tidak berubah menjadi sikap merendahkan.', 'Internasionalisme menekankan kerja sama antarbangsa yang setara; menyalami lawan menunjukkan sportivitas, tetapi inti sikap atlet adalah berkorban demi tim nasional.', 'Kosmopolitanisme menempatkan diri sebagai warga dunia di atas ikatan kebangsaan; atlet justru menolak tawaran klub luar negeri demi tim nasional.', 'Primordialisme berpusat pada ikatan suku, agama, atau daerah asal; yang dibela atlet adalah tim nasional, bukan kelompok primordial.'],
  ['Suara mayoritas belum mengatasi hambatan akses.', 'Hambatan sudah diketahui dan dana penyesuaian tersedia.', 'Manfaat tidak hanya dihitung dari jumlah pendukung.', 'Akses fasilitas umum tidak menjadi beban kelompok terdampak saja.'],
  ['Bahasa daerah bukan bahasa negara yang ditetapkan Pasal 36.', 'Jumlah peserta tidak mengubah ketentuan bahasa negara.', 'Bahasa mitra bukan ketentuan Pasal 36.', 'Pilihan panitia tidak menetapkan bahasa negara.'],
  ['Bobot khusus tetap membuat penilaian tidak setara.', 'Janji pribadi tidak menyediakan mekanisme pengendalian konflik.', 'Nama kontak tidak menghilangkan hubungan kepentingan.', 'Konflik perlu ditangani sebelum keputusan, bukan sesudahnya.'],
  ['Rencana tidak membuktikan kehadiran aktual.', 'Perkiraan terbesar dapat melebihkan jumlah aktual.', 'Rata-rata perkiraan bukan pengganti bukti hadir.', 'Target tidak menjadi bukti realisasi.'],
  ['Penerima tetap dapat memakai salinan lama.', 'Koreksi catatan pribadi tidak mencapai unit penerima.', 'Tanggung jawab koreksi berada pada pengirim data.', 'Penyesuaian agregat menyembunyikan sumber kesalahan.'],
  ['Catatan umum masih mencampur status final dan sementara.', 'Data yang sudah valid tetap dapat dilaporkan.', 'Target bukan realisasi terverifikasi.', 'Tanda tangan tambahan tidak memverifikasi data.'],
  ['Stimulus tidak membandingkan waktu penyelesaian.', 'Stimulus tidak menyebut penggunaan teknologi.', 'Petugas justru menerapkan aturan, bukan pengecualian.', 'Relasi personal tidak menjelaskan konsistensi aturan.'],
  ['Penggantian kata sandi kemudian tidak memulihkan jejak identitas.', 'Catatan kertas tidak mengubah identitas dalam sistem.', 'Pesan terhapus tidak membuat berbagi kata sandi sesuai peran.', 'Pengawasan pemilik tidak menggantikan akun resmi pengguna.'],
  ['Penghapusan membuat temuan terbukti hilang dari laporan.', 'Komitmen belum membuktikan pelaksanaan.', 'Hubungan baik bukan dasar bobot temuan.', 'Apresiasi tidak menggantikan pencatatan temuan.'],
  ['Pelaporan tidak membuktikan semua risiko dapat dihindari.', 'Pengakuan kejadian tidak menjamin citra selalu baik.', 'Stimulus tidak memberikan kewenangan menetapkan ganti rugi.', 'Melaporkan bukan bukti kemampuan memperbaiki alat.'],
  ['Pasal 27 ayat (1) mengatur kesamaan kedudukan dalam hukum.', 'Pasal 28D ayat (1) membahas kepastian dan perlindungan hukum.', 'Pasal 31 ayat (1) membahas hak pendidikan.', 'Pasal 36 membahas bahasa negara.'],
  ['Bela negara tidak terbatas pada tugas pertahanan atau kegiatan militer; undang-undang mengakui pengabdian sesuai profesi sebagai bentuk keikutsertaan warga negara.', 'Analis bekerja sama dengan dinas kesehatan, bukan mengambil alih tugasnya; kontribusi warga melengkapi tanggung jawab negara dan tidak menggantikannya.', 'Bela negara sesuai profesi dijalankan dalam batas kompetensi; analis justru tepat tidak menangani pasien, dan kontribusinya tetap bermakna tanpa tindakan medis.', 'Kontribusi ini memang menunjukkan kepedulian sosial, tetapi karena memakai keahlian profesi untuk melindungi masyarakat dari ancaman wabah, kontribusi itu juga termasuk bela negara; kedua pengertian itu tidak saling meniadakan.'],
  ['Label belum pasti tidak mencegah penyebaran informasi salah.', 'Banyaknya pembagian tidak memverifikasi konteks.', 'Foto terbaru di grup belum membuktikan waktu kejadian.', 'Informasi terverifikasi tetap dibutuhkan warga.'],
  ['Pekerjaan ini aman dan sesuai sertifikat relawan, tetapi tenda kesehatan sudah melayani pasien tanpa antrean sehingga kebutuhan itu sudah tertangani.', 'Donasi dapat menambah persediaan, tetapi gudang posko sudah menyimpan cukup obat dan air bersih; yang kurang adalah tenaga pengirim.', 'Meningkatkan kemampuan adalah langkah yang baik, tetapi tim evakuasi sudah lengkap dan dua dusun sudah dua hari belum menerima pasokan, padahal kemampuan mengemudi relawan dapat dipakai sekarang.', 'Tim evakuasi sudah lengkap, dan arahan singkat tidak menggantikan pelatihan memasuki bangunan rusak sehingga langkah ini berisiko menambah korban.'],
  ['Cinta tanah air tampak pada rasa bangga, perhatian pada lingkungan, dan pelestarian budaya bangsa; kasus ini tidak memuat perilaku itu.', 'Rela berkorban menuntut pengorbanan kepentingan pribadi bagi kepentingan bangsa; membayar pajak dan menyampaikan usulan merupakan pelaksanaan kewajiban dan hak warga negara yang biasa.', 'Kesetiaan pada Pancasila tampak saat mempertahankan dasar negara dari paham pengganti; kasus ini tidak menyinggung persoalan ideologi.', 'Kemampuan awal bela negara berkaitan dengan kesiapan fisik, kesiapan psikis, dan keterampilan dasar; kasus ini tidak memperlihatkannya.'],
  ['Dampaknya mencakup kesehatan dan penghidupan, bukan tampilan saja.', 'Ketahanan juga dipengaruhi ancaman nonmiliter.', 'Air berkaitan langsung dengan kesehatan warga.', 'Stimulus menyebut gangguan mata pencaharian.'],
  ['Jumlah paket sudah tepat, tetapi warga Pesisir yang persediaannya sudah habis harus menunggu sehari tanpa pangan sementara Lembah masih memiliki persediaan untuk 7 hari.', 'Urutan pengiriman sudah tepat, tetapi data Lembah sudah diverifikasi; verifikasi ulang hanya menunda hak 600 keluarga.', 'Pembagian sama banyak tidak mengikuti jumlah keluarga: Pesisir menerima 150 paket lebih dari kebutuhannya, sedangkan 150 keluarga di Lembah tidak menerima paket.', 'Pesisir terlayani lebih dahulu, tetapi 300 keluarga di Lembah tidak menerima haknya padahal paket mencukupi untuk semua keluarga; cadangan tidak diperlukan karena data sudah terverifikasi.'],
  ['Pengukuran batas negara memerlukan petugas dan alat resmi; hasil ukur dari ponsel yang diumumkan kepada warga dapat memicu klaim baru.', 'Unggahan terbuka membawa persoalan batas negara ke ruang publik dan melewati jalur pelaporan resmi.', 'Niatnya melindungi wilayah, tetapi mengubah letak patok merusak bukti dan bersandar pada ingatan warga.', 'Pemantauan tambahan terlihat teliti, tetapi laporan awal belum disampaikan sehingga dugaan pergeseran belum ditangani; petugas cukup melaporkan kondisi yang ditemukan.'],
  ['Federal berbeda dari kesatuan.', 'Republik berbeda dari monarki.', 'Konfederasi tidak sesuai bentuk kesatuan.', 'Baik federasi maupun monarki berbeda dari ketentuan pasal.'],
  ['Hak milik pribadi (Pasal 28H ayat (4)) dilanggar bila harta diambil alih secara sewenang-wenang; tidak ada pengambilalihan dalam kasus ini.', 'Kepastian hukum berkaitan dengan aturan yang jelas dan dapat diketahui; persyaratan izin dalam kasus sudah jelas dan diumumkan, sedangkan yang dipersoalkan adalah pengecualian bagi pejabat.', 'Praduga tak bersalah berlaku bagi tersangka atau terdakwa dalam perkara pidana; kasus ini tidak memuat dugaan pidana.', 'Pembatasan kewenangan relevan bila pejabat memakai wewenang jabatannya; dalam kasus ini ia bertindak sebagai pemilik usaha dan izin diterbitkan dinas lain.'],
  ['Urutan usulan tidak menunjukkan kualitas pertimbangan.', 'Sumbangan dana bukan dasar meniadakan kepentingan warga lain.', 'Rincian usulan tidak menggantikan musyawarah.', 'Dukungan tanpa pembahasan kebutuhan belum menjalankan musyawarah.'],
  ['Bantuan akses berbeda dari keistimewaan tanpa dasar.', 'Proses identik dapat menyisakan hambatan bagi pengguna.', 'Kebutuhan akses sah tidak bergantung pada hubungan pribadi.', 'Bantuan membaca tidak menghapus syarat substantif.'],
  ['Sila pertama terutama menyangkut ketuhanan.', 'Sila kedua terutama menyangkut kemanusiaan.', 'Sila ketiga terutama menyangkut persatuan.', 'Sila kelima terutama menyangkut keadilan sosial.'],
  ['Kesatuan tidak berarti semua kebiasaan harus sama.', 'Keragaman tetap dapat terhubung dalam kerja sama.', 'Dominasi satu identitas tidak mewakili persatuan dalam keragaman.', 'Penghormatan keragaman berlaku juga dalam kehidupan bersama.'],
  ['Nama sekolah pada kuitansi tetap dapat dikenali, dugaan tersebar kepada banyak wali murid sebelum diperiksa, dan grup percakapan tidak dapat memeriksa pungutan itu.', 'Rapat terbuka membuka dugaan kepada banyak orang sebelum ada pemeriksaan, dan komite sekolah bukan pihak yang bertugas memeriksa pungutan.', 'Kehormatan pihak lain terjaga, tetapi kepala sekolah mungkin terlibat dalam keputusan pungutan; penyelesaian yang ditentukan olehnya belum menghasilkan pemeriksaan independen oleh pihak yang berwenang.', 'Surat pembaca yang tidak menyebut sekolah tidak menunjuk pungutan tertentu sehingga tidak dapat ditindaklanjuti, dan hak menyampaikan pendapat tidak dipakai untuk memperoleh pemeriksaan.'],
  ['Bendera diatur pada Pasal 35.', 'Bahasa diatur pada Pasal 36.', 'Lagu kebangsaan diatur pada Pasal 36B.', 'Lambang diatur pada Pasal 36A.'],
  ['Awalan di- pada “diterima” dipisah dari kata dasarnya padahal harus serangkai, sedangkan “di loket” dan “diperiksa” sudah benar.', '“Diterima” dan “diperiksa” sudah benar, tetapi “di loket” menunjukkan tempat sehingga kata depan di harus dipisah dari kata yang mengikutinya.', '“Diterima” dan “di loket” sudah benar, tetapi awalan di- pada “diperiksa” dipisah dari kata dasarnya.', 'Ketiga bentuk keliru: awalan di- pada “diterima” dan “diperiksa” dipisah, sedangkan kata depan di pada “diloket” dirangkaikan; semuanya kebalikan dari kaidah.'],
  ['Kalimat (1) dan (5) benar, tetapi kalimat (2) keliru karena koma tidak dipakai sebelum kata “bahwa”.', 'Memuat dua kalimat keliru: kalimat (2) karena koma sebelum “bahwa” dan kalimat (4) karena koma sebelum anak kalimat yang mengiringi induk kalimat; hanya kalimat (3) yang benar.', 'Kalimat (1) dan (3) benar, tetapi kalimat (4) keliru karena anak kalimat “apabila lapangan tergenang” mengiringi induk kalimat sehingga tidak didahului koma.', 'Kalimat (3) dan (5) benar, tetapi memasukkan kalimat (4) yang memakai koma sebelum anak kalimat pengiring induk kalimat, padahal koma itu tidak diperlukan.'],
  ['Perincian tidak sejajar: “pembayaran biaya administrasi” berupa kata benda mengikuti dua kata kerja.', 'Subjek hilang: kata depan “dalam” menjadikan “pendaftaran ulang ini” keterangan sehingga predikat “mewajibkan” tidak memiliki subjek.', 'Pleonasme: “terlebih dahulu” dan “sebelum” sama-sama menyatakan urutan waktu sehingga salah satunya mubazir.', 'Konjungsi ganda: “walaupun” dan “tetapi” dipakai bersamaan sehingga kalimat tidak padu.'],
  ['Pembuka “Bagi” menjadikan kelompok peserta keterangan, dan “agar segera melengkapinya” adalah anak kalimat; kalimat tidak memiliki induk dan subjek meskipun objek sudah dinyatakan dengan “-nya”.', 'Frasa “agar segera” belum menyebutkan tindakan yang harus segera dilakukan, dan pembuka “Kepada peserta” tidak memperjelas subjek pada konstruksi tersebut.', 'Kata depan “dari” menandai asal, bukan pelaku; kalimat bermakna permintaan berasal dari peserta, dan “melengkapi” juga masih tanpa objek.', 'Subjek sudah jelas, tetapi bentuk pasif “dilengkapi” membuat peserta menjadi pihak yang dilengkapi, padahal yang harus dilengkapi adalah berkas; kalimat menjadi tidak logis.'],
  ['Pembakaran sekam dan keluhan asap hanya latar masalah pada kalimat (2), bukan gagasan yang menyatukan seluruh paragraf.', 'Pelatihan oleh koperasi adalah langkah penyelesaian pada kalimat (3); teks tidak menyebut pelatihan itu sebagai sumber penghematan utama, dan paragraf berfokus pada hasil pemanfaatan sekam.', 'Penurunan biaya bahan bakar benar, tetapi hanya rincian pada kalimat (4) dan belum mencakup perubahan sekam dari limbah menjadi sumber penghematan.', 'Saran berhenti membakar sekam tidak dinyatakan dalam paragraf; pernyataan ini melampaui isi teks.'],
  ['Belum terpisahnya pengaruh bukan bukti tidak ada pengaruh.', 'Data belum membuktikan satu penyebab tunggal.', 'Tim B tidak mengalami kenaikan waktu layanan.', 'Perubahan dua faktor pada tim A tidak membuktikan efektivitas di semua unit.'],
  ['Petugas kebersihan memang disebut paling dekat dengan frasa penunjuk, tetapi maknanya berkaitan dengan sampah, bukan penerangan.', 'Dua dusun adalah tempat lampu dipasang dan “gelap” adalah keadaan sebelum ada lampu; keduanya bukan sarana penerangan yang dirujuk.', 'Sampah yang tidak menumpuk adalah hasil dari penambahan petugas kebersihan, bukan unsur yang dimaksud dengan penerangan.', 'Rasa aman adalah akibat yang dinyatakan dalam kalimat (3), bukan unsur sebelumnya yang dirujuk oleh frasa penunjuk.'],
  ['Akses forum belum membuktikan aktivitas diskusi.', 'Premis tidak membalik hubungan materi daring dan akses.', 'Subkelompok yang tidak aktif belum diketahui.', 'Memiliki akses tidak pasti berarti memakai materi daring.'],
];
// Butir hasil revisi akademik (tahap 2) = butir dengan alasan kunci tersendiri; dipakai scripts/twk-checks.ts.
export const twkRevisedIds = items.flatMap((item, i) => item[7] ? ['twk-case-v2-' + i] : []);
export const twkCases: BankItem[] = items.map(([topic, subtopic, difficulty, bloom, stem, texts, explanation, keyReason, tip, reason], i) => ({
  id: 'twk-case-v2-' + i, subtest: 'TWK', topic, subtopic, difficulty, bloom, stem, answer: 0, explanation, ...(tip ? { tip } : {}),
  options: texts.map((text, index) => ({ text, score: index === 0 ? 5 : 0,
    reason: index === 0 ? keyReason ?? explanation : misconceptions[i][index - 1] })),
  difficultyReason: reason ?? (difficulty === 'mudah' ? 'Mengenali satu konsep atau satu kaidah yang dinyatakan.' : difficulty === 'sedang' ? 'Menerapkan konsep pada konteks dan membedakan dasar keputusan.' : 'Membandingkan beberapa informasi atau kepentingan dan membatasi kesimpulan.'),
  source: topic === 'Bahasa Negara' ? (/bacaan|pernyataan|gagasan/.test(subtopic) ? 'Bacaan orisinal v2; pembahasan berdasarkan informasi dalam stimulus.' : eyd) : (topic === 'Pilar Negara' || subtopic.includes('konstitusional') || subtopic === 'Identitas nasional' ? constitution : 'Kasus orisinal v2; cakupan TWK mengacu pada Riset Seleksi CPNS 2027 JadiASN.'),
}));
